class Solution {
public:
    int min1(int a , int b)
    {
        return ((a<b)?a:b) ;
    }
    int max1(int a , int b)
    {
        return ((a>b)?a:b) ;
    }
    int maxArea(vector<int>& A) 
    {
        int l = 0;
        int len = A.size() ;
        int r = len - 1;
        int area = 0;

        while (l < r)
        {
            area = max1(area, min1(A[l], A[r]) * (r - l));

            if (A[l] < A[r])
                l += 1;

        else
            r -= 1;
        }
        return area;   
    }
};
